CREATE TABLE public.currency_confirmations (store_id uuid PRIMARY KEY REFERENCES public.stores(id), rand_rate numeric NOT NULL CHECK(rand_rate>0), confirmed_by uuid NOT NULL, confirmed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.currency_confirmations TO authenticated; GRANT ALL ON public.currency_confirmations TO service_role;
ALTER TABLE public.currency_confirmations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read own currency confirmation" ON public.currency_confirmations FOR SELECT TO authenticated USING(store_id=public.current_store_id() AND public.is_staff(auth.uid()));
CREATE OR REPLACE FUNCTION public.save_currency_settings(p_zig_rate numeric,p_rand_rate numeric,p_confirm_rand boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid:=public.current_store_id(); BEGIN IF sid IS NULL OR NOT public.can_manage_payment_types(auth.uid()) THEN RAISE EXCEPTION 'Only owners and managers can change currencies'; END IF; IF p_zig_rate IS NULL OR p_rand_rate IS NULL OR p_zig_rate<=0 OR p_rand_rate<=0 OR p_zig_rate::text IN ('NaN','Infinity','-Infinity') OR p_rand_rate::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Enter positive exchange rates'; END IF; UPDATE public.settings SET zig_rate=p_zig_rate,rand_rate=p_rand_rate,updated_at=now() WHERE store_id=sid; IF NOT FOUND THEN RAISE EXCEPTION 'Store settings not found'; END IF; DELETE FROM public.currency_confirmations WHERE store_id=sid; IF p_confirm_rand IS TRUE THEN INSERT INTO public.currency_confirmations(store_id,rand_rate,confirmed_by) VALUES(sid,p_rand_rate,auth.uid()); END IF; END $$;
REVOKE ALL ON FUNCTION public.save_currency_settings(numeric,numeric,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_currency_settings(numeric,numeric,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.clear_changed_rand_confirmation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.rand_rate IS DISTINCT FROM OLD.rand_rate THEN DELETE FROM public.currency_confirmations WHERE store_id=NEW.store_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER clear_changed_rand_confirmation AFTER UPDATE OF rand_rate ON public.settings FOR EACH ROW EXECUTE FUNCTION public.clear_changed_rand_confirmation();
CREATE OR REPLACE FUNCTION public.require_confirmed_rand_checkout() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.currency='ZAR' AND NOT EXISTS(SELECT 1 FROM public.currency_confirmations c JOIN public.settings s ON s.store_id=c.store_id AND s.rand_rate=c.rand_rate WHERE c.store_id=NEW.store_id) THEN RAISE EXCEPTION 'Confirm the Rand conversion in Currency settings before Rand checkout'; END IF; RETURN NEW; END $$;
CREATE TRIGGER require_confirmed_rand_sale BEFORE INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.require_confirmed_rand_checkout();
CREATE TRIGGER require_confirmed_rand_payment BEFORE INSERT ON public.sale_payments FOR EACH ROW EXECUTE FUNCTION public.require_confirmed_rand_checkout();